CREATE FUNCTION public.hotel_convert_enquiry(p_request_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.booking_requests;b uuid;p jsonb; x jsonb; acc text; sid uuid; q numeric; BEGIN SELECT * INTO r FROM public.booking_requests WHERE id=p_request_id FOR UPDATE; IF r.id IS NULL OR r.service_type NOT IN ('hotel_dog','hotel_cat') OR r.kind<>'new' THEN RAISE EXCEPTION 'Hotel enquiry not found'; END IF; IF NOT public.user_has_permission(r.tenant_id,'bookings.edit') THEN RAISE EXCEPTION 'Booking edit permission required'; END IF; IF r.converted_booking_id IS NOT NULL THEN RETURN r.converted_booking_id; END IF; IF r.status='declined' THEN RAISE EXCEPTION 'Enquiry was declined'; END IF;
acc:=NULLIF(r.request_payload->'pets'->0->>'accommodation','');
INSERT INTO public.bookings(tenant_id,customer_id,booking_number,service_type,status,source,start_at,end_at,start_date,end_date,notes_customer,requires_transport) VALUES(r.tenant_id,r.customer_id,public.next_booking_number(r.tenant_id),r.service_type,'requested',r.source,r.preferred_start_at,r.preferred_end_at,(r.preferred_start_at AT TIME ZONE 'Africa/Johannesburg')::date,(r.preferred_end_at AT TIME ZONE 'Africa/Johannesburg')::date,r.customer_notes,COALESCE((r.request_payload->>'pickup_required')::boolean,false) OR COALESCE((r.request_payload->>'dropoff_required')::boolean,false)) RETURNING id INTO b;
FOR p IN SELECT * FROM jsonb_array_elements(COALESCE(r.request_payload->'pets','[]')) LOOP IF NOT EXISTS(SELECT 1 FROM public.pets WHERE id=(p->>'id')::uuid AND customer_id=r.customer_id AND tenant_id=r.tenant_id) THEN RAISE EXCEPTION 'Invalid enquiry pet'; END IF; INSERT INTO public.booking_pets(tenant_id,booking_id,pet_id,accommodation_type) VALUES(r.tenant_id,b,(p->>'id')::uuid,NULLIF(p->>'accommodation','')); END LOOP;
INSERT INTO public.hotel_booking_details(tenant_id,booking_id,accommodation_type,pickup_required,dropoff_required) VALUES(r.tenant_id,b,acc,COALESCE((r.request_payload->>'pickup_required')::boolean,false),COALESCE((r.request_payload->>'dropoff_required')::boolean,false));
FOR x IN SELECT * FROM jsonb_array_elements(COALESCE(r.request_payload->'addons','[]')) LOOP SELECT id INTO sid FROM public.hotel_surcharges WHERE tenant_id=r.tenant_id AND active AND code=x->>'code'; q:=COALESCE((x->>'quantity')::numeric,1)*(SELECT count(*) FROM public.booking_pets WHERE booking_id=b); IF sid IS NOT NULL THEN INSERT INTO public.hotel_booking_surcharges(tenant_id,booking_id,surcharge_id,quantity,quantity_basis) VALUES(r.tenant_id,b,sid,q,CASE WHEN x->>'code' ILIKE '%walk%' THEN 'total' ELSE 'catalog' END); END IF; END LOOP;
INSERT INTO public.hotel_booking_reviews(tenant_id,booking_id) VALUES(r.tenant_id,b) ON CONFLICT DO NOTHING;
UPDATE public.booking_requests SET status='converted',converted_booking_id=b,reviewed_at=now(),reviewed_by=public.current_profile_id() WHERE id=r.id; RETURN b; END $$;
REVOKE ALL ON FUNCTION public.hotel_convert_enquiry(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.hotel_convert_enquiry(uuid) TO authenticated,service_role;